(function(){
'use strict';
const KEY='nawaf-hq-v5';
const APPS={mueen:{name:'مُعِين',url:'https://mueen-islamic-app.vercel.app/',repo:'https://github.com/uauz1/mueen-islamic-app'},qaddha:{name:'قدّها',url:'https://qaddha.vercel.app/',repo:'https://github.com/uauz1/game'}};
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason:reason||'secretary'}}))}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function ensure(){let box=document.getElementById('exec-secretary');if(box)return box;box=document.createElement('div');box.id='exec-secretary';box.innerHTML='<button id="exec-secretary-toggle" type="button"><span class="exec-icon">✦</span><span><b>السكرتير التنفيذي</b><small id="exec-secretary-sub">متابع أعمال الشركة</small></span><i id="exec-secretary-count">0</i></button><aside id="exec-secretary-panel"><div class="exec-head"><div><span>EXECUTIVE SECRETARY</span><h2>ملخص نواف التنفيذي</h2></div><button id="exec-secretary-close" type="button">×</button></div><div id="exec-secretary-body"></div></aside>';document.body.appendChild(box);box.querySelector('#exec-secretary-toggle').onclick=()=>box.classList.toggle('open');box.querySelector('#exec-secretary-close').onclick=()=>box.classList.remove('open');return box}
function taskKey(t){return `${t.id}:${t.status}:${t.lastRunAt||t.executionStartedAt||''}`}
function resultText(t){return String(t?.aiResult?.summary||t?.aiResult?.deliverable||t?.blockedReason||'').trim()}
function employee(s,t){return (s.employees||[]).find(e=>e.id===t.employeeId)}
function projectName(s,t){return (s.projects||[]).find(p=>p.id===t.projectId)?.name||APPS[t.projectId]?.name||'الشركة'}
function createBriefs(){const s=read();s.secretaryBriefs=Array.isArray(s.secretaryBriefs)?s.secretaryBriefs:[];s.secretarySeen=Array.isArray(s.secretarySeen)?s.secretarySeen:[];let added=0;for(const t of (s.tasks||[])){if(!['COMPLETED','WAITING_FOR_NAWAF'].includes(t.status))continue;const k=taskKey(t);if(s.secretarySeen.includes(k))continue;const e=employee(s,t),result=resultText(t);s.secretaryBriefs.unshift({id:'sec'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),key:k,taskId:t.id,status:t.status,projectId:t.projectId||'',title:t.title,employee:e?.name||'موظف AI',project:projectName(s,t),result:result|| (t.status==='COMPLETED'?'تمت المهمة وحُفظت نتيجتها.':'المهمة تحتاج قرارك.'),at:new Date().toISOString(),read:false});s.secretarySeen.unshift(k);added++}s.secretarySeen=s.secretarySeen.slice(0,250);s.secretaryBriefs=s.secretaryBriefs.slice(0,80);if(added){localStorage.setItem(KEY,JSON.stringify(s));showLatest(s.secretaryBriefs[0])}render()}
function showLatest(b){let n=document.querySelector('.exec-popup');if(!n){n=document.createElement('div');n.className='exec-popup';document.body.appendChild(n)}n.innerHTML=`<div class="exec-popup-mark">✦</div><div><b>${b.status==='COMPLETED'?'تم إنجاز مهمة':'فيه شيء يحتاج قرارك'}</b><span>${esc(b.employee)} • ${esc(b.project)}</span><p>${esc(b.result.slice(0,180))}</p></div>`;n.classList.add('show');n.onclick=()=>{ensure().classList.add('open');markAllRead()};clearTimeout(showLatest.t);showLatest.t=setTimeout(()=>n.classList.remove('show'),7000)}
function markAllRead(){const s=read();for(const b of (s.secretaryBriefs||[]))b.read=true;localStorage.setItem(KEY,JSON.stringify(s));render()}
function render(){const root=ensure(),s=read(),briefs=s.secretaryBriefs||[],unread=briefs.filter(b=>!b.read).length,active=(s.tasks||[]).filter(t=>['WORKING','RESEARCHING','REVIEWING'].includes(t.status)),waiting=(s.tasks||[]).filter(t=>t.status==='WAITING_FOR_NAWAF');root.querySelector('#exec-secretary-count').textContent=unread;root.querySelector('#exec-secretary-count').style.display=unread?'grid':'none';root.querySelector('#exec-secretary-sub').textContent=active.length?`${active.length} مهمة تعمل الآن`:waiting.length?`${waiting.length} بانتظار قرارك`:'كل شيء تحت المتابعة';root.querySelector('#exec-secretary-body').innerHTML=`<section class="exec-summary"><div><b>${active.length}</b><span>تعمل الآن</span></div><div><b>${waiting.length}</b><span>بانتظارك</span></div><div><b>${(s.tasks||[]).filter(t=>t.status==='COMPLETED').length}</b><span>مكتملة</span></div></section><section class="exec-apps"><h3>التطبيقات المرتبطة</h3>${Object.entries(APPS).map(([id,a])=>`<article><div><b>${a.name}</b><small>${a.url.replace('https://','')}</small></div><div><a href="${a.url}" target="_blank" rel="noopener">فتح التطبيق</a><a href="${a.repo}" target="_blank" rel="noopener">GitHub</a></div></article>`).join('')}</section><section class="exec-briefs"><div class="exec-section-head"><h3>آخر التقارير التنفيذية</h3>${unread?'<button id="exec-mark-read" type="button">تمت القراءة</button>':''}</div>${briefs.length?briefs.slice(0,20).map(b=>`<article class="${b.read?'':'unread'}"><header><span>${b.status==='COMPLETED'?'✓ مكتمل':'! يحتاجك'}</span><time>${new Date(b.at).toLocaleString('ar-SA')}</time></header><h4>${esc(b.title)}</h4><small>${esc(b.employee)} • ${esc(b.project)}</small><p>${esc(b.result.slice(0,420))}</p>${APPS[b.projectId]?`<a href="${APPS[b.projectId].url}" target="_blank" rel="noopener">فتح ${APPS[b.projectId].name} ↗</a>`:''}</article>`).join(''):'<div class="exec-empty">أول ما تخلص مهمة، السكرتير بيجيب لك نتيجتها هنا.</div>'}</section>`;const m=root.querySelector('#exec-mark-read');if(m)m.onclick=markAllRead}
let t;function schedule(){clearTimeout(t);t=setTimeout(createBriefs,250)}window.addEventListener('nawaf:state-updated',schedule);document.addEventListener('DOMContentLoaded',()=>{ensure();createBriefs()});setInterval(createBriefs,5000);window.NawafExecutiveSecretary={open:()=>ensure().classList.add('open'),refresh:createBriefs};
})();